#!/usr/bin/env python3
'''CPU-only, standalone semantic and invariant checks for K-SYS-005. No GPU, NCCL, files, subprocess, or network.'''

from math import isclose


def allreduce_ref(xs):
    p = len(xs)
    if p == 0:
        raise ValueError('empty participants')
    n = len(xs[0])
    for row in xs:
        if len(row) != n:
            raise ValueError('count mismatch')
    out = []
    for _ in range(p):
        row = []
        for i in range(n):
            total = 0
            for s in range(p):
                total += xs[s][i]
            row.append(total)
        out.append(row)
    return out


def allgather_ref(xs):
    p = len(xs)
    if p == 0:
        raise ValueError('empty participants')
    n = len(xs[0])
    for row in xs:
        if len(row) != n:
            raise ValueError('count mismatch')
    merged = []
    for s in range(p):
        for value in xs[s]:
            merged.append(value)
    return [list(merged) for _ in range(p)]


def reduce_scatter_ref(xs, n):
    p = len(xs)
    if p == 0:
        raise ValueError('empty participants')
    for row in xs:
        if len(row) != p * n:
            raise ValueError('input count mismatch')
    total = []
    for j in range(p * n):
        value = 0
        for s in range(p):
            value += xs[s][j]
        total.append(value)
    out = []
    for r in range(p):
        out.append(total[r * n:(r + 1) * n])
    return out


def broadcast_ref(root, xs):
    p = len(xs)
    if p == 0:
        raise ValueError('empty participants')
    if not (0 <= root < p):
        raise ValueError('root out of range')
    n = len(xs[0])
    for row in xs:
        if len(row) != n:
            raise ValueError('count mismatch')
    return [list(xs[root]) for _ in range(p)]


def logical_trace_error(traces):
    if len(traces) == 0:
        return 'no ranks'
    length = len(traces[0])
    for r, trace in enumerate(traces):
        if len(trace) != length:
            return 'length mismatch at rank ' + str(r)
    for i in range(length):
        first = traces[0][i]
        for r in range(1, len(traces)):
            if traces[r][i] != first:
                return 'ticket mismatch at slot ' + str(i)
    return None


def shape_only_error(traces):
    if len(traces) == 0:
        return 'no ranks'
    lengths = set()
    for trace in traces:
        lengths.add(len(trace))
    if len(lengths) != 1:
        return 'length mismatch'
    for i in range(len(traces[0])):
        counts = set()
        for r in range(len(traces)):
            counts.add(traces[r][i][2])
        if len(counts) != 1:
            return 'count mismatch'
    return None


TRANSITIONS = {
    ('PREPARED', 'open'): 'GROUP_OPEN',
    ('PREPARED', 'fail'): 'FAILED',
    ('GROUP_OPEN', 'close_success'): 'ISSUED',
    ('GROUP_OPEN', 'close_progress'): 'ISSUE_PENDING',
    ('GROUP_OPEN', 'abort'): 'ABORTED',
    ('ISSUE_PENDING', 'poll_success'): 'ISSUED',
    ('ISSUE_PENDING', 'poll_error'): 'FAILED',
    ('ISSUE_PENDING', 'abort'): 'ABORTED',
    ('ISSUED', 'device_done'): 'DEVICE_DONE',
    ('ISSUED', 'fail'): 'FAILED',
    ('DEVICE_DONE', 'publish'): 'PUBLISHED',
    ('DEVICE_DONE', 'fail'): 'FAILED',
}


def next_state(state, event):
    return TRANSITIONS.get((state, event), 'REJECT')


def naive_next_state(state, event):
    if event == 'publish':
        return 'PUBLISHED'
    return next_state(state, event)


def failure_closure(events):
    failed = set()
    aborted = set()
    for rank, event in events:
        if event == 'local_fail':
            failed.add(rank)
        elif event == 'abort':
            aborted.add(rank)
        elif event == 'timeout':
            pass
        elif event == 'publish':
            if failed:
                return 'publish after failure'
        elif event == 'finish':
            if failed and rank not in aborted:
                return 'finish without abort'
    for rank in failed:
        if rank not in aborted:
            return 'failed rank not closed'
    return None


def ring_closed(p, nbytes, alpha, beta):
    if p < 1 or nbytes < 0 or alpha < 0 or beta <= 0:
        raise ValueError('invalid cost input')
    if p == 1:
        return 0.0
    return 2 * (p - 1) * alpha + 2 * (p - 1) * nbytes / (p * beta)


def ring_steps(p, nbytes, alpha, beta):
    if p == 1:
        return 0.0
    total = 0.0
    for _ in range(2 * (p - 1)):
        total += alpha + (nbytes / p) / beta
    return total


def bad_ring(p, nbytes, alpha, beta):
    if p == 1:
        return 0.0
    return (p - 1) * alpha + (p - 1) * nbytes / (p * beta)


def group_peak(sizes):
    return sum(sizes)


def sequential_peak(sizes):
    if len(sizes) == 0:
        return 0
    return max(sizes)


def main_buffer_bytes(kind, p, n, b, root=False):
    if kind == 'allreduce':
        return 2 * n * b
    if kind == 'allgather':
        return (p + 1) * n * b
    if kind == 'reducescatter':
        return (p + 1) * n * b
    if kind == 'reduce':
        if root:
            return 2 * n * b
        return n * b
    if kind == 'broadcast':
        return n * b
    raise ValueError('unknown operation')


def check_semantics():
    p = 4
    n = 8
    xs = []
    for r in range(p):
        row = []
        for i in range(n):
            row.append(100 * r + i)
        xs.append(row)
    ar = allreduce_ref(xs)
    expected = [600 + 4 * i for i in range(n)]
    for row in ar:
        assert row == expected
    ag = allgather_ref(xs)
    expected_ag = []
    for s in range(p):
        for i in range(n):
            expected_ag.append(100 * s + i)
    for row in ag:
        assert row == expected_ag
    wide = []
    for r in range(p):
        row = []
        for j in range(p * n):
            row.append(100 * r + j)
        wide.append(row)
    rs = reduce_scatter_ref(wide, n)
    for r in range(p):
        expected_rs = []
        for t in range(n):
            expected_rs.append(600 + 4 * (r * n + t))
        assert rs[r] == expected_rs
    bc = broadcast_ref(2, xs)
    for row in bc:
        assert row == xs[2]
    for one_p in (1, 2, 3):
        one = []
        for r in range(one_p):
            row = []
            for i in range(5):
                row.append(7 * r + i)
            one.append(row)
        assert len(allreduce_ref(one)) == one_p
        assert allgather_ref(one)[0] == [v for row in one for v in row]
        wide_one = []
        for r in range(one_p):
            row = []
            for j in range(one_p * 5):
                row.append(100 * r + j)
            wide_one.append(row)
        assert len(reduce_scatter_ref(wide_one, 5)) == one_p
    empty = [[], [], []]
    assert allreduce_ref(empty) == [[], [], []]
    assert allgather_ref(empty) == [[], [], []]
    assert reduce_scatter_ref([[] for _ in range(3)], 0) == [[], [], []]
    assert broadcast_ref(1, empty) == [[], [], []]
    print('semantics: p=4 n=8 allreduce[0][0]=' + str(ar[0][0]) + ' allreduce[3][7]=' + str(ar[3][7]))
    print('semantics: p=1 and zero-length edges accepted by the reference formulas')


def check_identity():
    common = [
        (7, 0, 8, 'int32', 'allreduce', None),
        (8, 0, 8, 'int32', 'allreduce', None),
    ]
    valid = [list(common) for _ in range(4)]
    assert logical_trace_error(valid) is None
    bad_skip = [list(common) for _ in range(4)]
    bad_skip[0] = bad_skip[0][1:]
    assert logical_trace_error(bad_skip) is not None
    bad_slot = [list(common) for _ in range(4)]
    bad_slot[0][0] = (8, 0, 8, 'int32', 'allreduce', None)
    assert logical_trace_error(bad_slot) is not None
    assert shape_only_error(bad_slot) is None
    print('identity: skip rejected=' + str(logical_trace_error(bad_skip) is not None) + ' slot mismatch rejected=' + str(logical_trace_error(bad_slot) is not None))
    print('negative control: shape-only check accepted the same-count wrong-slot trace; identity check rejected it')


def check_completion_states():
    assert next_state('PREPARED', 'open') == 'GROUP_OPEN'
    assert next_state('GROUP_OPEN', 'close_progress') == 'ISSUE_PENDING'
    assert next_state('ISSUE_PENDING', 'poll_success') == 'ISSUED'
    assert next_state('ISSUE_PENDING', 'publish') == 'REJECT'
    assert next_state('ISSUED', 'publish') == 'REJECT'
    assert next_state('ISSUED', 'device_done') == 'DEVICE_DONE'
    assert next_state('DEVICE_DONE', 'publish') == 'PUBLISHED'
    state = 'PREPARED'
    for event in ('open', 'close_progress', 'poll_success', 'device_done', 'publish'):
        state = next_state(state, event)
        assert state != 'REJECT'
    assert state == 'PUBLISHED'
    assert naive_next_state('ISSUE_PENDING', 'publish') == 'PUBLISHED'
    print('completion states: early consume rejected; naive state machine was detected as faulty')


def check_failure_closure():
    good = [(0, 'local_fail'), (0, 'abort'), (1, 'timeout'), (1, 'abort'), (2, 'abort'), (3, 'abort')]
    assert failure_closure(good) is None
    bad_finish = [(0, 'local_fail'), (1, 'finish')]
    assert failure_closure(bad_finish) is not None
    bad_publish = [(0, 'local_fail'), (1, 'publish')]
    assert failure_closure(bad_publish) is not None
    print('failure closure: survivor finish rejected=' + str(failure_closure(bad_finish) is not None) + ' survivor publish rejected=' + str(failure_closure(bad_publish) is not None))


def check_costs_and_capacity():
    alpha = 5e-6
    beta = 40 * 1024 ** 3
    for p in (1, 2, 4, 8):
        for nbytes in (0, 8192, 16 * 1024 * 1024):
            a = ring_closed(p, nbytes, alpha, beta)
            b = ring_steps(p, nbytes, alpha, beta)
            assert isclose(a, b, rel_tol=1e-12, abs_tol=0.0)
    t = ring_closed(4, 8192, alpha, beta)
    bad = bad_ring(4, 8192, alpha, beta)
    assert not isclose(t, bad, rel_tol=1e-12, abs_tol=0.0)
    b = 4
    n = 8
    assert main_buffer_bytes('allreduce', 4, n, b) == 64
    assert main_buffer_bytes('allgather', 4, n, b) == 160
    assert main_buffer_bytes('reducescatter', 4, n, b) == 160
    assert main_buffer_bytes('reduce', 4, n, b, True) == 64
    assert main_buffer_bytes('reduce', 4, n, b, False) == 32
    assert main_buffer_bytes('broadcast', 4, n, b) == 32
    bad_allgather = 4 * n * b
    assert bad_allgather != main_buffer_bytes('allgather', 4, n, b)
    sizes = [3, 5, 7]
    assert group_peak(sizes) == 15
    assert sequential_peak(sizes) == 7
    assert group_peak(sizes) != sequential_peak(sizes)
    print('cost: closed-form ring and step sum agree; p=4 nbytes=8192 time=' + str(t))
    print('negative controls: omitted-factor ring formula and missing-allgather-plus-one capacity were detected')
    print('capacity: group peak 15 differs from sequential peak 7 for staged buffers')


def main():
    check_semantics()
    check_identity()
    check_completion_states()
    check_failure_closure()
    check_costs_and_capacity()
    print('coverage: exact rank semantics, p=1 and empty inputs, logical identity, issue/device/consume states, failure closure, ideal ring cost, group capacity, buffer formulas')
    print('not measured: any GPU, NCCL, network, or learner effect')


if __name__ == '__main__':
    main()
